var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(/* ... */);
builder.Services.AddAuthorization();

var app = builder.Build();

if (!app.Environment.IsDevelopment())
{
    app.UseExceptionHandler("/error");
    app.UseHsts();
}

app.UseHttpsRedirection();
app.UseRouting();
app.UseAuthentication();
app.UseAuthorization();
app.MapControllers();
app.Run();

// WRONG — authorization cannot see endpoint metadata
app.UseAuthentication();
app.UseAuthorization();
app.UseRouting(); // too late
app.MapControllers();

// Symptom: [Authorize] ignored or 404 before 401
// Fix: UseRouting immediately before auth middleware

// WRONG
app.UseRouting();
app.MapControllers();
app.UseExceptionHandler(); // never catches controller exceptions

// Controller throw → 500 raw or empty body
// Fix: UseExceptionHandler before UseRouting

app.Use(async (context, next) =>
{
    await next();
    var endpoint = context.GetEndpoint()?.DisplayName;
    var status = context.Response.StatusCode;
    if (status is 401 or 403 or 404)
    {
        var log = context.RequestServices.GetRequiredService<ILoggerFactory>()
            .CreateLogger("AuthOrder");
        log.LogWarning("{Status} Path={Path} Endpoint={Endpoint}",
            status, context.Request.Path, endpoint ?? "none");
    }
});
// Register AFTER UseRouting to see endpoint name on auth failures
